const MAX_SDP_LINES=4096;const MAX_SDP_LINE_BYTES=4096;const MAX_MEDIA_SECTIONS=8;function assertOpenAIRealtimeAudioOnlyOffer(e){const t=e.split(/\r\n|\n|\r/u);if(t.length>MAX_SDP_LINES)throw new Error(`OpenAI Realtime SDP offer has too many lines`);let n=0;let r=0;for(const e of t){if(Buffer.byteLength(e,`utf8`)>MAX_SDP_LINE_BYTES)throw new Error(`OpenAI Realtime SDP offer line is too large`);if(!e.startsWith(`m=`))continue;if(++n>MAX_MEDIA_SECTIONS)throw new Error(`OpenAI Realtime SDP offer has too many media sections`);const t=/^m=([A-Za-z0-9-]+)\s+(\d+)(?:\/\d+)?(?:\s|$)/u.exec(e);if(!t?.[1]||!t[2])throw new Error(`OpenAI Realtime SDP offer has an invalid media section`);const i=t[1].toLowerCase();const a=Number(t[2])!==0;if(i===`audio`)r+=Number(a);else if(i!==`application`||a)throw new Error(`OpenAI Realtime Gateway control does not support ${i} media`)}if(r===0)throw new Error(`OpenAI Realtime Gateway control requires active audio media`)}export{assertOpenAIRealtimeAudioOnlyOffer as t};